#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc <= 2) {
        printf("Usage: ./argv_index index\n");
        return 1;
    }

    int index = atoi(argv[1]);

    if (index < 1 || index > argc) {
        printf("Invalid argument index.\n");
        return 1;
    }

    int i;
    for (i = 0; i < argc; ++i) {
        if (i + 1 == index) {
            printf("%s\n", argv[i]);
            break;
        }
    }

    return 0;
}
```

This code takes two command line arguments: the first is the name of the program, and the second is the index of the argument to print. It checks if the input is valid and then prints the corresponding argument from the command line arguments.

