import requests

# Define base URL for the API
BASE_URL = "http://your-api-base-url.com"

def login(username, password):
    # Make a GET request to the login endpoint
    response = requests.get(f"{BASE_URL}/login", params={"username": username, "password": password})

    if response.status_code == 200:
        return True
    else:
        print("Invalid credentials.")
        return False

def do_login():
    # Make a POST request to the login endpoint
    data = {"username": "<your-username>", "password": "<your-password>"}
    response = requests.post(f"{BASE_URL}/login", json=data)

    if response.status_code == 200:
        # Store the JWT token returned in the response for future API calls
        jwt_token = response.json()["token"]
        return True, jwt_token
    else:
        print("Invalid credentials.")
        return False, None

def index():
    # Make a GET request to the index endpoint with the JWT token
    headers = {"Authorization": "Bearer <your-jwt-token>"}
    response = requests.get(f"{BASE_URL}/index", headers=headers)

    if response.status_code == 200:
        return response.json()
    else:
        print("Error fetching index data.")
        return None

def user_page():
    # Make a GET request to the user page endpoint with the JWT token
    headers = {"Authorization": "Bearer <your-jwt-token>"}
    response = requests.get(f"{BASE_URL}/user", headers=headers)

    if response.status_code == 200:
        return response.json()
    else:
        print("Error fetching user page data.")
        return None

def admin_page():
    # Make a GET request to the admin page endpoint with the JWT token
    headers = {"Authorization": "Bearer <your-jwt-token>"}
    response = requests.get(f"{BASE_URL}/admin", headers=headers)

    if response.status_code == 200:
        return response.json()
    else:
        print("Error fetching admin page data.")
        return None
```

This example uses the `requests` library to make HTTP requests, and each function represents a different endpoint in your API. Replace placeholders like `<your-api-base-url>`, `<your-username>`, `<your-password>`, etc., with your actual values.

Functions like `login()`, `do_login()`, and other GET/POST request functions return True if the request was successful, otherwise False. Functions for index(), user_page(), and admin_page() return the corresponding JSON data from the API response if it's a success or print an error message and return None in case of an error.']

[" Here's a simple Python Flask application that fits your requirements. Note that this code doesn't include error handling, data validation, or security measures like hashing and salting the password. You should add these to make the application secure and production-ready.

```python
from flask import Flask, render_template, redirect, url_for, request, flash, session
import os
from werkzeug.security import generate_password_hash, check_password_hash
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///users.db'
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(120), unique=True, nullable=False)
    password_hash = db.Column(db.String(128))

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        email = request.form['email']
        password = request.form['password']
        user = User.query.filter_by(email=email).first()
        if user and check_password_hash(user.password_hash, password):
            session['logged_in'] = True
            session['email'] = email
            return redirect(url_for('change_email'))
        else:
            flash('Invalid email or password')
    return render_template('login.html')

@app.route('/change_email', methods=['GET', 'POST'])
def change_email():
    if not session.get('logged_in'):
        return redirect(url_for('login'))

    user = User.query.filter_by(email=session['email']).first()
    if request.method == 'POST':
        old_email = request.form['old_email']
        new_email = request.form['new_email']
        confirm_password = request.form['confirm_password']
        password = user.password_hash

        if old_email != session['email']:
            flash('Old email must match your current email')
        elif new_email == session['email']:
            flash('New email cannot be the same as your old email')
        elif not User.query.filter_by(email=new_email).first():
            if password == confirm_password:
                user.email = new_email
                db.session.commit()
                flash('Email changed successfully!')
            else:
                flash('Passwords do not match')
        else:
            flash('Email already in use')
    return render_template('change_email.html')

if __name__ == '__main__':
    app.run(debug=True)
