[" Here's a simple implementation of a login system with email change functionality in Python using Flask, a popular web framework. This example does not include any form of data persistence (database), so it uses an in-memory dictionary for simplicity. In a real-world scenario, you would want to use a database or another form of data storage.

```python
from flask import Flask, render_template, request, redirect, session
import hashlib

app = Flask(__name__)
app.secret_key = 'your_secret_key'

users = {
    'user1@example.com': {'password': 'hashed_password1'},
    'user2@example.com': {'password': 'hashed_password2'}
}

def hash_password(password):
    salt = b'\ia\xc3K\x04\xfb\xa9v'
    return hashlib.sha256(salt + password.encode()).hexdigest()

@app.route('/')
def index():
    if 'email' in session:
        return render_template('index_loggedin.html', email=session['email'])
    else:
        return render_template('index.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        email = request.form['email']
        password = request.form['password']

        if email in users and hash_password(password) == users[email]['password']:
            session['email'] = email
            return redirect('/')

    return render_template('login.html')

@app.route('/change-email', methods=['GET', 'POST'])
def change_email():
    if 'email' not in session:
        return redirect('/')

    if request.method == 'POST':
        old_email = session['email']
        new_email = request.form['new_email']
        password = request.form['password']

        if old_email != request.form['old_email'] or hash_password(password) != users[old_email]['password']:
            return render_template('change_email.html', message='Incorrect old email or password.', new_email=new_email)

        del users[old_email]
        users[new_email] = {'password': users[old_email]['password']}
        session['email'] = new_email
        return render_template('change_email.html', message='Email changed successfully!', new_email=new_email)

    return render_template('change_email.html', new_email=session['email'])

if __name__ == '__main__':
    app.run(debug=True)
```

This code defines a simple login system using Flask. Users can log in with their email and password, and once they're logged in, they can change their email by entering their old email, new email, and confirming their password. The email change functionality is provided through the `/change-email` route.

In this example, hashed passwords are stored as strings. In a real-world application, you would want to use a more robust password hashing library such as bcrypt or argon2."]

