// Function to calculate checksum of a buffer
unsigned int calculate_checksum(const char *buffer, size_t length) {
    unsigned int checksum = 0;
    for (size_t i = 0; i < length; ++i)
        checksum ^= buffer[i];
    return checksum;
}

int main() {
    FILE *inputFile, *outputFile;
    char *buffer;
    size_t bytesRead = 0;
    unsigned int checksum;

    // Open input and output files
    inputFile = fopen("input.txt", "r");
    if (!inputFile) {
        perror("Error opening input file.");
        return 1;
    }

    outputFile = fopen("output.txt", "w");
    if (!outputFile) {
        perror("Error opening output file.");
        fclose(inputFile);
        return 1;
    }

    // Read the input file into a buffer
    fseek(inputFile, 0, SEEK_END);
    size_t fileSize = ftell(inputFile);
    rewind(inputFile);

    buffer = malloc(fileSize + 1);
    if (!buffer) {
        perror("Error allocating memory.");
        fclose(inputFile);
        fclose(outputFile);
        return 1;
    }

    bytesRead = fread(buffer, sizeof(char), fileSize, inputFile);
    if (bytesRead != fileSize) {
        perror("Error reading from the input file.");
        free(buffer);
        fclose(inputFile);
        fclose(outputFile);
        return 1;
    }

    // Add null terminator to the buffer
    buffer[bytesRead] = '\0';

    checksum = calculate_checksum(buffer, bytesRead);

    // Write number of bytes read and checksum to the output file
    fprintf(outputFile, "Bytes read: %zu\nChecksum: %u\n", bytesRead, checksum);

    free(buffer);
    fclose(inputFile);
    fclose(outputFile);

    return 0;
}
```

This code reads the contents of a file called `input.txt` into a buffer, calculates its checksum, and saves the number of bytes read and the checksum to another file called `output.txt`. If the file is empty, the checksum will be 0.']

