```c
#include <stdio.h>
#include <stdlib.h>
#include <sys/stat.h>
#include <unistd.h>

void save_data(const char *filename, size_t bytes_read, uint32_t checksum) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        perror("Error creating output file");
        return;
    }

    fprintf(file, "Bytes read: %zu\n", bytes_read);
    fprintf(file, "Checksum: %u\n", checksum);
    fclose(file);
}

uint32_t calculate_checksum(const void *buffer, size_t length) {
    const uint8_t *data = buffer;
    uint32_t checksum = 0;

    for (size_t i = 0; i < length; ++i) {
        checksum ^= data[i];
    }

    return checksum;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s input_file output_file\n", argv[0]);
        return 1;
    }

    const char *input_filename = argv[1];
    const char *output_filename = argv[2];

    struct stat file_info;
    if (stat(input_filename, &file_info) == -1) {
        perror("Error getting input file information");
        return 1;
    }

    size_t file_size = file_info.st_size;
    char *buffer = malloc(file_size);

    if (buffer == NULL) {
        perror("Error allocating memory for buffer");
        return 1;
    }

    FILE *file = fopen(input_filename, "r");
    if (file == NULL) {
        perror("Error opening input file");
        free(buffer);
        return 1;
    }

    size_t bytes_read = fread(buffer, 1, file_size, file);
    if (bytes_read != file_size) {
        perror("Error reading from input file");
        free(buffer);
        fclose(file);
        return 1;
    }

    uint32_t checksum = calculate_checksum(buffer, file_size);
    save_data(output_filename, bytes_read, checksum);

    free(buffer);
    fclose(file);

    return 0;
}
