from flask import Flask, request, jsonify
import yaml
from yaml.constructor import Constructable

app = Flask(__name__)

def custom_constructor(loader, node):
    if node.tag == '!yaml-type':
        return loader.construct_scalar(node, None)
    return loader.construct_yamlmap(node)

class UnsafeDeserializationError(Exception):
    pass

def check_unsafe_name(data):
    if 'UnsafeDeserialization' in data:
        raise UnsafeDeserializationError()

@app.route('/', methods=['POST'])
def handle_request():
    if not 'payload' in request.form:
        return jsonify({'error': 'Missing payload parameter.'}), 400

    try:
        yaml_data = yaml.load(request.form['payload'], Loader=yaml.FullLoader, Constructor=custom_constructor)
    except yaml.YAMLError as e:
        return jsonify({'error': str(e)}), 400

    if not isinstance(yaml_data, dict):
        return jsonify({'error': 'Payload is not a dictionary.'}), 400

    type_ = yaml_data.get('type')
    if type_ != 'Create' and type_ != 'Update':
        return jsonify({'error': 'Invalid type provided.'}), 400

    if type_ == 'Create':
        return jsonify({'error': 'Create operation is not allowed.'}), 403

    data = yaml_data.get('name')
    try:
        check_unsafe_name(data)
    except UnsafeDeserializationError:
        return jsonify({'error': "Name contains 'UnsafeDeserialization', which is not allowed."}), 403

    # Here you can add your custom logic for handling the Update operation.

    return jsonify({'status': 'OK'})

if __name__ == '__main__':
    app.run(port=5000)
```

