[' Here's a simple Flask web application that fulfills your requirements. It includes two functions to return product price and calculate total price for a given product code and quantity, as well as a route to handle these requests.

```python
from flask import Flask, request, jsonify

app = Flask(__name__)
products = {
    "A": 10,
    "B": 20,
    "C": 30
}

def get_product_price(code):
    if code in products:
        return products[code]
    else:
        return None

def calculate_total_price(code, quantity):
    price = get_product_price(code)
    if price is not None:
        return price * quantity
    else:
        return None

@app.route('/api/v1/price', methods=['GET'])
def calculate_price():
    code = request.args.get('code')
    quantity = int(request.args.get('quantity'))
    total_price = calculate_total_price(code, quantity)
