[' Here are two ways to achieve this in C using both `system()` and `popen()`.

1. Using `system()`:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s username output_file\n", argv[0]);
        return -1;
    }

    char cmd[128] = "";
    sprintf(cmd, "getent passwd %s > %s", argv[1], argv[2]);

    system(cmd);

    FILE *output = fopen(argv[2], "r");
    if (output == NULL) {
        perror("Error opening output file");
        return -1;
    }

    char c;
    while ((c = getc(output)) != EOF) {
        putchar(c);
    }

    fclose(output);
    return 0;
}
```

2. Using `popen()`:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s username output_file\n", argv[0]);
        return -1;
    }

    FILE *output = fopen(argv[2], "w");
    if (output == NULL) {
        perror("Error opening output file");
        return -1;
    }

    char cmd[128] = "";
    sprintf(cmd, "getent passwd %s", argv[1]);

    FILE *pipe = popen(cmd, "r");
    if (!pipe) {
        perror("Error executing command");
        return -1;
    }

    char c;
    while ((c = fgetc(pipe)) != EOF) {
        fputc(c, output);
    }

    pclose(pipe);
    fclose(output);

    FILE *input = fopen(argv[2], "r");
    if (input == NULL) {
        perror("Error opening output file");
        return -1;
    }

    while ((c = getc(input)) != EOF) {
        putchar(c);
    }

    fclose(input);
    return 0;
}
```

These programs will take a username and an output file as arguments, execute the command `getent passwd <username>` either using `system()` or `popen()`, and store the output in the specified file. The first version uses `system()` to run the command synchronously and redirect the output to a file; the second version uses `popen()` to create a pipe, execute the command asynchronously, and write its output to a file before reading and displaying the contents of that file.']

