void exec_command(const char *cmd) {
    FILE *pipe = popen(cmd, "r");
    if (!pipe) exit(1);

    char buffer[128];
    size_t n;
    while ((n = fgets(buffer, sizeof(buffer), pipe)) > 0)
        printf("%s", buffer);

    pclose(pipe);
}

