#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

int main() {
    srand(time(NULL));

    const int NUM_FLOATS = 3;
    float floats[NUM_FLOATS];

    // Generate random floats between 0 and 100
    for (int i = 0; i < NUM_FLOATS; ++i) {
        floats[i] = ((float)rand() / RAND_MAX) * 100.0f;
    }

    // Allocate memory for float-to-string conversion
    char* floatStrings[NUM_FLOATS];
    for (int i = 0; i < NUM_FLOATS; ++i) {
        floatStrings[i] = (char*) malloc(sizeof(float) * sizeof(char));
        snprintf(floatStrings[i], sizeof(floatStrings[i]), "%.2f", floats[i]);
    }

    // Combine the strings into a single one, separated by commas
