    }

    // Write the output string to a file named "output.txt"
    FILE *file = fopen("output.txt", "w");
    if (file != NULL) {
        fprintf(file, "%s\n", outputString);
        fclose(file);
    }

    // Cleanup memory allocation
    for (int i = 0; i < NUM_FLOATS; ++i) {
        free(floatStrings[i]);
    }
    free(outputString);

    return 0;
}
