['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    // Check for exactly one argument
    if (argc != 2) {
        printf("Usage: %s <string>\n", argv[0]);
        return 1;
    }

    // Check if the argument is a string
    if (!isalpha(argv[1][0])) {
        printf("Error: Argument must be a string.\n");
        return 1;
    }

    int strLen = strlen(argv[1]);

    // Trim trailing whitespace
    for (int i = strLen - 1; i >= 0 && argv[1][i] == ' '; --i) {
        argv[1][i] = '\0';
        strLen -= 1;
    }

    // Trim newlines
    for (int i = 0; argv[1][i]; ++i) {
        if (argv[1][i] == '\n') {
            argv[1][i] = '\0';
            strLen -= 1;
        }
    }

    // Null terminate the string
    argv[1][strLen] = '\0';

    return 0;
}
```
This C code takes one argument (a string) from the command line, checks if it's exactly one argument and that it is a string. It then removes trailing whitespace and newlines, and null-terminates the string. The program returns an error code of 1 if any of the conditions are not met, otherwise it returns 0.']

