[' Here's a simple C code example using the Boost.Beast asio library, which provides a high-level C++ HTTP/1 Web Server framework. In this example, we will create a function `http_hello_page` that handles requests for "/hello" and sends a personalized HTML page in response.

```cpp
#include <boost/beast/core.hpp>
#include <boost/beast/http.hpp>
#include <cstdlib>
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <thread>
#include <boost/asio/ip/tcp.hpp>
#include <boost/bind.hpp>

namespace http = boost::beast::http;
using tcp = boost::asio::ip::tcp;

void http_hello_page(http::request<http::string_body> req, std::ostream& outputbuf) {
    // Check if the request method is GET
    if (req.method() != http::verb::get) {
        outputbuf.write(
            boost::asio::buffer("HTTP/1.0 405 Method Not Allowed\r\nContent-Type: text/plain\r\n\r\nMethod Not Allowed.\r\n"));
        return;
    }

    // Extract the request body (username)
    auto const& body = req.body();
    std::istream is(body.data(), body.size());

    if (!std::getline(is, username)) {
        outputbuf.write(
            boost::asio::buffer("HTTP/1.0 400 Bad Request\r\nContent-Type: text/plain\r\n\r\nInvalid request.\r\n"));
        return;
    }

    // Construct the response body (HTML page)
    std::stringstream ss;
    ss << "HTTP/1.0 200 OK\r\n"
       << "Content-Type: text/html\r\n\r\n"
       << "<!DOCTYPE html>\n"
       << "<html lang='en'>\n<head>\n<meta charset='UTF-8' />\n<title>Hello, " << username << "</title></head>\n"
       << "<body>\n<h1>Hello, " << username << "!</h1>\n</body>\n</html>";
    outputbuf.write(boost::asio::buffer(ss.str()));
}

void handle_request(tcp::socket socket) {
    try {
        auto constexpr bufferSize = 8 * 1024;
        char buf[bufferSize];

        beast::flat_buffer requestBuffer;
        http::request<http::string_body> req;
        bool more = true;
        while (more) {
            size_t len = socket.read_some(boost::asio::buffer(buf, bufferSize));
            if (!len)
                break; // Connection closed

            requestBuffer.commit(len);
            req.parse(requestBuffer);
            more = !req.need_eof();
        }

        std::ostream outputbuf;
        http_hello_page(req, outputbuf);

        beast::flat_buffer responseBuffer;
        http::response<http::string_body> res{http::status::ok, req.version(), req.target()};
        res.set(http::field::server, "Web Server Example");
        res.keep_alive(req.keep_alive());
        res.body().assign(outputbuf.str());
        res.prepare_payload();

        socket.write(boost::asio::buffer(res));
    } catch (const beast::system_error& se) {
        if (se.code() != boost::system::errc::not_connected)
            std::cerr << "Error: " << se.what() << "\n";
    }
}

int main(int argc, char* argv[]) {
    try {
        tcp::acceptor acceptor{io};
        acceptor.open(endpoint);
        acceptor.listen(so_max_conn);

        while (true) {
            auto c = acceptor.accept();
            std::thread t{handle_request, std::move(c)};
            t.detach();
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << "\n";
        return EXIT_FAILURE;
    }
}
```

This code sets up a simple HTTP server using Boost.Asio library. It listens for incoming connections on the specified endpoint and port (not defined in this example). When it receives a request for "/hello", the `http_hello_page` function is called to handle the request, read the username from the request body, construct an HTML response with the given username, write the response to the output buffer, and send it back to the client.

Before running this code, make sure you have Boost library installed on your system and compile it using a C++14-compliant compiler.']

