[' Here's the C code for the requested functions `http_hello_page` and an auxiliary function `escape_html`. I assume that you have the necessary includes (such as `stdio.h`, `stdlib.h`, and others) and appropriate data structures for handling file streams.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Escape HTML special characters */
char *escape_html(const char *str) {
    int len = strlen(str);
    char *escaped = (char *)malloc((len + 3) * sizeof(char));
    int i, j = 0;

    for (i = 0; i < len; i++) {
        switch (str[i]) {
            case '<':
                escaped[j++] = '&';
                escaped[j++] = 'l';
                escaped[j++] = 't';
                escaped[j++] = '/';
                escaped[j++] = '>';
                break;
            case '>':
                escaped[j++] = '&';
                escaped[j++] = 'g';
                escaped[j++] = 't';
                escaped[j++] = '>';
                break;
            case '&':
                escaped[j++] = '&';
                escaped[j++] = 'a';
                escaped[j++] = 'm';
                escaped[j++] = 'p';
                escaped[j++] = ';';
                break;
            default:
                escaped[j++] = str[i];
        }
    }

    escaped[j] = '\0';
    return escaped;
}

/* Construct and send a "hello [username]" response */
void http_hello_page(FILE *request, FILE *response) {
    char username[256]; // Assume username is maximum 255 characters (including null character)
    fgets(username, sizeof(username), request);
    username[strlen(username) - 1] = '\0'; // Remove the newline character

    char *escaped_username = escape_html(username);

    /* Write response to the output file stream */
    fprintf(response, "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n");
    fprintf(response, "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <title>Hello Page</title>\n</head>\n<body>\n  <h1>hello %s</h1>\n</body>\n</html>", escaped_username);

    free(escaped_username); // Free memory after usage
}
```

This code defines two functions: `http_hello_page` and `escape_html`. The former reads the username from a request file stream, constructs a response string with "hello [username]", escapes any special HTML characters using the `escape_html` function, and writes the response to an output file stream. The latter function escapes certain special characters (<, >, &) within an input string for safe use in HTML documents.']

